def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    my = [h[0] for h in history]
    opp = [h[1] for h in history]
    total_opp_def = opp.count('D')
    total_my_def = my.count('D')

    if n == 99:
        return 'D'
    if total_opp_def == n:
        return 'D'

    if n < 10:
        if n >= 2 and opp[-1] == 'D' and opp[-2] == 'D':
            return 'D'
        if total_opp_def >= 3:
            return 'D'
        return 'C'

    retaliated = False
    for i in range(n - 1):
        if my[i] == 'D' and opp[i+1] == 'D':
            retaliated = True
            break

    if total_my_def == 0:
        if n == 10:
            return 'D'
        if opp[-1] == 'D':
            return 'D'
        return 'C'

    if not retaliated:
        if total_my_def == 1 and my[-1] == 'D':
            return 'C'
        else:
            return 'D'

    opp_after_c = 0
    opp_after_c_d = 0
    opp_after_d = 0
    opp_after_d_d = 0
    for i in range(n - 1):
        if my[i] == 'C':
            opp_after_c += 1
            if opp[i+1] == 'D':
                opp_after_c_d += 1
        else:
            opp_after_d += 1
            if opp[i+1] == 'D':
                opp_after_d_d += 1
    p_d_after_c = opp_after_c_d / opp_after_c if opp_after_c > 0 else 0.0
    p_d_after_d = opp_after_d_d / opp_after_d if opp_after_d > 0 else 0.0

    if p_d_after_d > p_d_after_c + 0.2:
        return 'C'
    if p_d_after_c > p_d_after_d + 0.25 and n > 20:
        return 'D'

    if opp[-1] == 'D':
        if opp[-3:].count('D') >= 2:
            return 'D'
        return 'C'
    return 'C'
